const RULES = [
  {
    "id": "db-privileged-login",
    "when": "\\b(psql|mysql|sqlcmd|mongosh)\\b[^\\n]*(-U\\s*|-u\\s*|--user(name)?[=\\s]+)(postgres|root|sa|admin)\\b",
    "reason": "高權帳號連錯密碼會觸發登入鎖定。",
    "fix": "改用測試帳號 app_test。"
  },
  {
    "id": "deploy",
    "when": "(^|[\\s/\\\\\"'])deploy\\.(sh|ps1)\\b|\\b(kubectl\\s+apply|terraform\\s+apply|helm\\s+(upgrade|install))\\b",
    "unless": "--dry-run\\b",
    "reason": "部署不可逆。",
    "fix": "先 --dry-run；真的要部署請使用者親自執行。"
  },
  {
    "id": "ssh-prod",
    "when": "\\b(ssh|scp|rsync)\\b[^\\n]*\\b[\\w.-]*(prod|prd)[\\w.-]*",
    "reason": "正式主機在熔斷清單上。",
    "fix": "請使用者親自操作。"
  },
  {
    "id": "destructive-sql",
    "when": "^(?=[^\\n]*\\b(psql|mysql|sqlcmd|sqlite3|mongosh|invoke-sqlcmd)\\b)(?=[^\\n]*(\\bDROP\\s+(TABLE|DATABASE|SCHEMA)\\b|\\bTRUNCATE\\b|\\bDELETE\\s+FROM\\s+[^\\s;\"']+(?![^;\\n]*\\bWHERE\\b)))",
    "reason": "整批毀掉資料。",
    "fix": "帶 WHERE 只刪自己造的列。"
  },
  {
    "id": "start-needs-env",
    "when": "\\b(npm|pnpm|yarn)\\s+(run\\s+)?(start|dev)\\b|\\bnode\\b[^\\n]*\\bserver\\.js\\b",
    "requireEnv": {
      "APP_ENV": "^(local|development)$"
    },
    "reason": "沒帶 APP_ENV 會靜默跑正式設定。",
    "fix": "APP_ENV=local npm start"
  },
  {
    "id": "git-push",
    "when": "\\bgit\\b[^\\n]*\\bpush\\b",
    "reason": "推送會改到共用分支。",
    "fix": "走專案的提交流程。"
  },
  {
    "id": "quoted-token",
    "when": "PROD_ADMIN_TOKEN",
    "matchQuoted": true,
    "reason": "正式環境管理權杖不得出現在指令裡。",
    "fix": "改用測試權杖。"
  }
];

